#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr;
    long num = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (num > 1000000000) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (num < 2) {
        printf("%ld^1", num);
    } else {
        int i;
        int count = 0;
        for (i = 2; i * i <= num; i++) {
            if (num % i == 0) {
                count++;
                printf("%d^%d ", i, count);
                num /= i;
                i--;
            }
        }
        if (num > 1) {
            printf("%ld^1", num);
        }
    }
    putchar('\n');
    return 0;
}
